const SOUNDS={"beep": "", "timer": "", "go": "", "bell": "", "bell2": "", "buzzer": ""};

const $=id=>document.getElementById(id);
const KEYS=['language','training-mode','number-min','number-max','number-colors','arrow-colors','arrow-color','dirs','duration','gap','rounds','color','theme','sound','volume','sound-type','interval-mode','gap-min','gap-max','sets','set-rest'];
const PALETTE={light:['#20ac78','#823ac7','#257bdd','#e2812b','#dc4168'],dark:['#3fcf95','#b483f2','#5ba6ff','#f5a04f','#ff6b8a']};
const DIRS={2:[90,270],4:[0,90,180,270],8:[0,45,90,135,180,225,270,315]};
const DIR_LABELS={0:'上',45:'右上',90:'右',135:'右下',180:'下',225:'左下',270:'左',315:'左上'};
const darkQuery=matchMedia('(prefers-color-scheme: dark)');

let state='idle',resumeState='',timer=null,next=null,due=0,left=0;
const DEFAULT_NUMBER_COLORS=["#d83842","#16816b","#f3cf46","#245fbd"];let lastNumberColor=-1;
let restFrame=0;
let round=0,set=1,restSeconds=0,last=-1,count=3,config={},wake=null;

/* ---------- 设置 ---------- */
function save(){try{localStorage.setItem('arrow-flow',JSON.stringify(Object.fromEntries(KEYS.map(k=>[k,$(k).value]))))}catch{}}
function load(){
  try{const s=JSON.parse(localStorage.getItem('arrow-flow')||'null');if(s)for(const k of KEYS)if(s[k]!=null)$(k).value=s[k]}catch{}
  if(!$('sound-type').value)$('sound-type').value='beep';
  if(!['zh','en'].includes($('language').value))$('language').value='zh';
  if(!$('theme').value)$('theme').value='system';
  if(!$('interval-mode').value)$('interval-mode').value='fixed';
}
function isDark(){const t=$('theme').value;return t==='dark'||(t==='system'&&darkQuery.matches)}
function applyTheme(){
  const t=$('theme').value,root=document.documentElement;
  if(t==='system')delete root.dataset.theme;else root.dataset.theme=t;
  document.querySelector('meta[name=theme-color]').content=isDark()?'#141815':'#ffffff';
}

/* ---------- 声音 ---------- */
let audioCtx=null,playing=null;const buffers={};
function soundOn(){return $('sound').value==='on'}
// iOS：让声音在静音开关打开时也能播放
const SILENT='data:audio/mpeg;base64,';
let keepAlive=null;
function iosPlayback(){
  try{if(navigator.audioSession){navigator.audioSession.type='playback'}}catch{}
  try{
    if(!keepAlive){keepAlive=new Audio(SILENT);keepAlive.loop=true;keepAlive.setAttribute('playsinline','');keepAlive.volume=0.01}
    keepAlive.play().catch(()=>{});
  }catch{}
}
function stopKeepAlive(){try{keepAlive?.pause()}catch{}}
async function loadSound(key,ctx){
  if(buffers[key])return;
  const bin=atob(SOUNDS[key]),u=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
  buffers[key]=await new Promise((res,rej)=>ctx.decodeAudioData(u.buffer,res,rej));
}
async function unlockSound(){
  if(!soundOn())return;
  try{
    iosPlayback();
    const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
    if(!audioCtx||audioCtx.state==='closed'||audioCtx.state==='interrupted'){
      const old=audioCtx;audioCtx=new AC();if(old)old.close().catch(()=>{});
    }
    const ctx=audioCtx;
    // Both resume and the silent source start inside the tap gesture, before awaiting decoding.
    const ready=ctx.state==='running'?Promise.resolve():ctx.resume();
    const prime=ctx.createBufferSource();prime.buffer=ctx.createBuffer(1,1,ctx.sampleRate);prime.connect(ctx.destination);prime.start();prime.onended=()=>prime.disconnect();
    await Promise.all([ready,loadSound($('sound-type').value,ctx)]);
    Promise.allSettled(Object.keys(SOUNDS).map(k=>loadSound(k,ctx)));
  }catch{}
}
function play(key){
  const vol=+$('volume').value/100,ctx=audioCtx;
  if(!soundOn()||vol<=0||!ctx)return;
  const requested=performance.now();
  const emit=()=>{
    if(!soundOn()||ctx!==audioCtx||ctx.state!=='running'||performance.now()-requested>500)return;
    const buf=buffers[key]||buffers.beep;if(!buf)return;
    try{
      if(playing)try{playing.stop()}catch{}
      const src=ctx.createBufferSource(),gain=ctx.createGain();
      src.buffer=buf;gain.gain.value=+$('volume').value/100;
      src.connect(gain);gain.connect(ctx.destination);src.start();
      playing=src;src.onended=()=>{src.disconnect();gain.disconnect();if(playing===src)playing=null};
    }catch{}
  };
  if(ctx.state==='running')emit();else ctx.resume().then(emit).catch(()=>{});
}
const cue=()=>play($('sound-type').value);

function syncSound(){
  const on=soundOn(),v=+$('volume').value,text=v===0?t('静音'):v+'%';
  $('sound').setAttribute('aria-checked',String(on));
  $('sound-panel').hidden=!on;
  $('volume').disabled=!on;
  $('preview').disabled=!on||v===0;
  $('volume-value').textContent=text;
  $('volume').setAttribute('aria-valuetext',text);
  $('volume').style.background=`linear-gradient(to right,var(--accent) ${v}%,var(--soft) ${v}%)`;
  $('mute').setAttribute('aria-label',t(on?'关闭声音':'开启声音'));
  $('icon-on').classList.toggle('hidden',!on);
  $('icon-off').classList.toggle('hidden',on);
}
function setSound(on){$('sound').value=on?'on':'off';syncSound();save();if(on)return unlockSound();else stopKeepAlive()}

/* ---------- 练习流程 ---------- */
function schedule(fn,ms){clearTimeout(timer);next=fn;left=ms;due=performance.now()+ms;timer=setTimeout(fn,ms)}
function show(id,on){$(id).classList.toggle('hidden',!on)}
function updatePhase(){
  const phase=t(state==='paused'?'已暂停':state==='countdown'?'准备开始':state==='rest'?(restSeconds<=3?'准备开始':'组间休息'):'');const preparing=(state==='rest'||state==='paused'&&resumeState==='rest')&&restSeconds<=3;const group=config.rounds?t('第 {current} / {total} 组',{current:preparing?set+1:set,total:config.sets}):'';const text=[group,phase].filter(Boolean).join(' · ');
  $('phase').textContent=text;
  $('phase').style.visibility=text?'visible':'hidden';
}
function setPauseIcon(paused){
  show('icon-pause',!paused);show('icon-play',paused);
  $('pause').setAttribute('aria-label',t(paused?'继续':'暂停'));
}
function updateCounter(){$('counter').textContent=config.rounds?round+' / '+config.rounds:String(round)}
async function keepAwake(){try{wake=await navigator.wakeLock?.request('screen')}catch{}}
function releaseWake(){try{wake?.release()}catch{}wake=null}
const clamp=(v,lo,hi,fallback)=>Math.max(lo,Math.min(hi,Number.isFinite(v)?v:fallback));

function start(){
  clearNumberCue();$('stage').classList.toggle('number-mode',$('training-mode').value==='numbers');
  $('stage').classList.remove('resting');
  cancelAnimationFrame(restFrame);
  if(!validateNumberRange())return;
  if(!validateIntervals()){openSettings();$('gap-max').focus();$('gap-max').reportValidity();return;}
  const requestedRounds=$('rounds').value.trim()===''?20:+$('rounds').value;
  $('rounds').value=String(Number.isFinite(requestedRounds)?Math.max(0,Math.min(Number.MAX_SAFE_INTEGER,Math.floor(requestedRounds))):20);sessionInfo();
  config={
    mode:$('training-mode').value,
    numberMin:+$('number-min').value,numberMax:+$('number-max').value,numberColors:numberPalette(),arrowColors:readPalette('arrow-colors'),arrowColor:$('arrow-color').value,
    dirs:+$('dirs').value,
    duration:clamp(+$('duration').value||1.5,.3,10,1.5)*1000,
    gap:clamp(+$('gap').value,0,10,.5)*1000,
    intervalMode:$('interval-mode').value,
    gapMin:clamp(+$('gap-min').value,0,10,.5)*1000,
    gapMax:clamp(+$('gap-max').value,0,10,1.5)*1000,
    rounds:+$('rounds').value,
    sets:+$('rounds').value?Math.round(clamp(+$('sets').value,1,99,1)):1,
    setRest:Math.round(clamp(+$('set-rest').value,0,600,30)),
    color:$('color').value
  };
  save();
  round=0;set=1;last=-1;lastNumberColor=-1;count=3;state='countdown';show('rest',false);
  $('stage').classList.remove('finished');$('stage').classList.add('active');
  show('result',false);show('controls',true);show('arrow',false);show('countdown',true);
  $('stage').classList.remove('paused');setCount(count);$('progress').style.width='0%';
  setPauseIcon(false);updatePhase();updateCounter();keepAwake();
  unlockSound().then(()=>{if(state==='countdown'&&count===3)cue()});
  schedule(tick,1000);
}
function setCount(n){
  $('count-num').textContent=n;
  const c=$('countdown');c.classList.remove('tick');void c.offsetWidth;c.classList.add('tick');
}
function tick(){
  count--;
  if(count>0){setCount(count);cue();schedule(tick,1000)}
  else{show('countdown',false);showArrow()}
}
function showArrow(){
  if(config.rounds&&round>=config.rounds)return completeSet();
  state='arrow';round++;
  if(config.mode==='numbers'){
    const n=randomNumber(config.numberMin,config.numberMax);
    const pool=config.numberColors;const colors=pool.map((_,i)=>i).filter(i=>pool.length===1||i!==lastNumberColor);
    lastNumberColor=colors[Math.floor(Math.random()*colors.length)];
    const bg=pool[lastNumberColor];$('stage').style.setProperty('--number-bg',bg);$('stage').classList.add('number-cue');$('stage').classList.toggle('number-light-bg',lightNumberBackground(bg));
    $('number-cue').style.fontSize='clamp(80px,'+Math.min(48,80/String(n).length)+'vmin,600px)';$('number-cue').textContent=n;$('number-cue').setAttribute('aria-label',t('数字 {n}',{n}));show('number-cue',true);show('arrow',false);
  }else{
  const options=config.dirs===2?DIRS[2]:DIRS[config.dirs].filter(d=>d!==last);
  last=options[Math.floor(Math.random()*options.length)];
  const pal=PALETTE[isDark()?'dark':'light'];
  const arrow=$('arrow');
  arrow.style.transform=`rotate(${last}deg)`;
  arrow.style.color=config.color==='green'?pal[0]:config.color==='black'?'var(--text)':config.color==='custom'?config.arrowColor:config.arrowColors[Math.floor(Math.random()*config.arrowColors.length)];
  arrow.setAttribute('aria-label',t(DIR_LABELS[last]));
  show('arrow',true);  }
  cue();updatePhase();updateCounter();
  $('progress').style.width=config.rounds?(round/config.rounds*100)+'%':'0%';
  schedule(blank,config.duration);
}
function clearNumberCue(){show('number-cue',false);$('stage').classList.remove('number-cue','number-light-bg');$('stage').style.removeProperty('--number-bg');}
function blank(){
  clearNumberCue();show('arrow',false);
  if(config.rounds&&round>=config.rounds)return completeSet();
  state='blank';updatePhase();
  schedule(showArrow,nextGap(config));
}
function completeSet(){
  if(set>=config.sets)return finish();
  restSeconds=config.setRest;
  if(restSeconds===0)return nextSet();
  state='rest';$('rest-next').textContent=t('下一组 · 第 {current} / {total} 组',{current:set+1,total:config.sets});
  show('arrow',false);show('rest',true);if(restSeconds>3)cue();renderRest();updatePhase();schedule(restTick,1000);animateRestRing();
}
function renderRest(){const preparing=restSeconds<=3;$('stage').classList.toggle('resting',!preparing);show('rest',!preparing);show('countdown',preparing);if(preparing){resetGroupProgress();setCount(restSeconds);cue();$('counter').textContent='0 / '+config.rounds;}else{$('rest-time').textContent=Math.floor(restSeconds/60)+':'+String(restSeconds%60).padStart(2,'0');}updatePhase();}
function animateRestRing(){
  cancelAnimationFrame(restFrame);
  const paused=state==='paused'&&resumeState==='rest';
  if((state!=='rest'&&!paused)||restSeconds<=3)return;
  const remaining=Math.max(0,(restSeconds-1)*1000+(paused?left:Math.max(0,due-performance.now())));
  $('rest-ring-fill').style.strokeDashoffset=String(1-Math.min(1,remaining/(config.setRest*1000)));
  if(!paused)restFrame=requestAnimationFrame(animateRestRing);
}
function restTick(){restSeconds--;if(restSeconds<=0)return nextSet();renderRest();schedule(restTick,1000);}
function resetGroupProgress(){const p=$('progress');p.style.transition='none';p.style.width='0%';void p.offsetWidth;p.style.transition='';}
function nextSet(){resetGroupProgress();$('stage').classList.remove('resting');cancelAnimationFrame(restFrame);set++;round=0;last=-1;show('rest',false);show('countdown',false);showArrow();}
function togglePause(){
  if(state==='idle'||state==='done')return;
  if(state==='paused'){
    state=resumeState;unlockSound();setPauseIcon(false);updatePhase();$('stage').classList.remove('paused');
    schedule(next,left);keepAwake();if(state==='rest')animateRestRing();
  }else{
    resumeState=state;state='paused';
    left=Math.max(0,due-performance.now());clearTimeout(timer);
    setPauseIcon(true);updatePhase();$('stage').classList.add('paused');if(resumeState==='rest')animateRestRing();
  }
}
function finish(){
  clearNumberCue();
  $('stage').classList.remove('resting');
  cancelAnimationFrame(restFrame);
  clearTimeout(timer);state='done';$('stage').classList.add('finished');$('stage').classList.remove('paused');
  show('arrow',false);show('rest',false);show('countdown',false);show('controls',false);show('result',true);
  updatePhase();
  releaseWake();stopKeepAlive();
}
function exit(){clearNumberCue();$('stage').classList.remove('resting');cancelAnimationFrame(restFrame);$('stage').classList.remove('finished');clearTimeout(timer);state='idle';$('stage').classList.remove('paused');$('stage').classList.remove('active');releaseWake();stopKeepAlive()}

/* ---------- 绑定 ---------- */
load();applyTheme();syncSound();
for(const k of KEYS)$(k).addEventListener('change',save);
$('theme').addEventListener('change',applyTheme);
darkQuery.addEventListener('change',applyTheme);
$('sound').onclick=()=>setSound(!soundOn());
$('mute').onclick=()=>{if(soundOn()){setSound(false);}else{if(+$('volume').value===0)$('volume').value='40';setSound(true).then(cue);}};
$('volume').oninput=()=>{syncSound();save()};
$('preview').onclick=async()=>{await unlockSound();cue()};
$('sound-type').addEventListener('change',()=>$('preview').click());
function paletteDefaults(key){return key==='arrow-colors'?[...PALETTE.light]:[...DEFAULT_NUMBER_COLORS];}
function readPalette(key){try{const colors=JSON.parse($(key).value);const valid=Array.isArray(colors)?colors.filter(c=>typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c)).slice(0,8):[];return valid.length?valid:paletteDefaults(key);}catch{return paletteDefaults(key);}}
function numberPalette(){return readPalette('number-colors');}
function paletteKey(){return $('training-mode').value==='numbers'?'number-colors':'arrow-colors';}
function lightNumberBackground(hex){const rgb=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]>.183;}
function renderNumberPalette(){
  const key=paletteKey(),palette=readPalette(key),list=$('number-palette');list.replaceChildren();
  palette.forEach((color,i)=>{
    const item=document.createElement('div');item.className='palette-item';
    const input=document.createElement('input');input.type='color';input.value=color;input.setAttribute('aria-label',t(key==='arrow-colors'?'箭头颜色 {n}':'背景颜色 {n}',{n:i+1}));input.oninput=()=>{palette[i]=input.value;$(key).value=JSON.stringify(palette);save();};
    const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',t('删除颜色 {n}',{n:i+1}));remove.disabled=palette.length===1;remove.onclick=()=>{palette.splice(i,1);$(key).value=JSON.stringify(palette);renderNumberPalette();save();};
    item.append(input,remove);list.append(item);
  });
  $('add-number-color').disabled=palette.length>=8;
}
function newPaletteColor(existing){
  const candidates=['#7745b5','#ec6d24','#15a6bd','#d54891','#6058d8','#ce8e26','#386c76','#963d61','#4250aa','#7d5a36'];
  const rgb=hex=>hex.slice(1).match(/../g).map(v=>parseInt(v,16));
  const used=existing.map(c=>c.toLowerCase()),colors=used.map(rgb);
  return candidates.filter(c=>!used.includes(c)).reduce((best,candidate)=>{
    const value=rgb(candidate),distance=Math.min(...colors.map(c=>Math.hypot(...value.map((v,i)=>v-c[i]))));
    return distance>best.distance?{color:candidate,distance}:best;
  },{color:'#000000',distance:-1}).color;
}
$('add-number-color').onclick=()=>{const key=paletteKey(),colors=readPalette(key);if(colors.length<8){colors.push(newPaletteColor(colors));$(key).value=JSON.stringify(colors);renderNumberPalette();save();}};
$('reset-number-colors').onclick=()=>{const key=paletteKey();$(key).value=JSON.stringify(paletteDefaults(key));renderNumberPalette();save();};
renderNumberPalette();
function randomNumber(min,max){return min+Math.floor(Math.random()*(max-min+1));}
function validateNumberRange(){
  if($('training-mode').value!=='numbers')return true;
  const low=$('number-min'),high=$('number-max');high.setCustomValidity('');
  if(low.validity.valid&&high.validity.valid&&+low.value>+high.value)high.setCustomValidity(t('最大数字不能小于最小数字。'));
  const invalid=[low,high].find(el=>!el.validity.valid);
  if(invalid){openSettings();invalid.focus();invalid.reportValidity();return false;}
  return true;
}
for(const k of ['number-min','number-max'])$(k).addEventListener('input',()=>{$('number-max').setCustomValidity('');sessionInfo();save()});
function syncTrainingMode(){
  const numbers=$('training-mode').value==='numbers';document.querySelector('.home').classList.toggle('number-home',numbers);
  for(const b of document.querySelectorAll('[data-mode]'))b.setAttribute('aria-pressed',String(b.dataset.mode===$('training-mode').value));
  $('dirs-field').hidden=numbers;$('color-field').hidden=numbers;$('number-range').hidden=!numbers;$('number-color-settings').hidden=!numbers&&$('color').value!=='random';$('custom-arrow-color').hidden=numbers||$('color').value!=='custom';$('palette-label').textContent=t(numbers?'数字背景颜色':'随机箭头颜色');$('palette-help').textContent=t(numbers?'点色块更换颜色，背景与数字独立随机。':'点色块更换颜色，每次随机显示一种箭头颜色。');$('home-arrow').style.color=$('color').value==='custom'?$('arrow-color').value:$('color').value==='black'?'var(--text)':'var(--accent)';renderNumberPalette();
  $('home-title').textContent=t(numbers?'数字反应':'箭头反应');show('home-arrow',!numbers);show('home-number',numbers);
}
for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>{$('training-mode').value=b.dataset.mode;syncTrainingMode();sessionInfo();save()};
syncTrainingMode();
$('color').addEventListener('change',syncTrainingMode);$('arrow-color').addEventListener('input',()=>{$('home-arrow').style.color=$('arrow-color').value;save()});
const presets=[...document.querySelectorAll('[data-speed]')];
function syncPresets(){
  const d=+$('duration').value,g=+$('gap').value;
  for(const b of presets){const random=$('interval-mode').value==='random';const [pd,pg,pm]=(random?b.dataset.randomSpeed:b.dataset.speed).split(',').map(Number);const matches=Math.abs(d-pd)<1e-9&&(random?Math.abs(+$('gap-min').value-pg)<1e-9&&Math.abs(+$('gap-max').value-pm)<1e-9:Math.abs(g-pg)<1e-9);b.setAttribute('aria-pressed',String(matches));}
}
presets.forEach(b=>b.onclick=()=>{if($('interval-mode').value==='random'){[$('duration').value,$('gap-min').value,$('gap-max').value]=b.dataset.randomSpeed.split(',');$('gap-max').setCustomValidity('');}else{[$('duration').value,$('gap').value]=b.dataset.speed.split(',');}syncPresets();save()});
for(const k of ['duration','gap'])$(k).addEventListener('input',()=>{syncPresets();save()});
syncPresets();
$('start').onclick=start;$('again').onclick=start;
$('pause').onclick=togglePause;$('exit').onclick=exit;$('back').onclick=()=>{exit();openSettings()};


function nextGap(c){return c.intervalMode==='random'?c.gapMin+Math.random()*(c.gapMax-c.gapMin):c.gap;}
function syncIntervals(){for(const b of document.querySelectorAll('[data-interval]'))b.setAttribute('aria-pressed',String(b.dataset.interval===$('interval-mode').value));const random=$('interval-mode').value==='random';$('fixed-interval').hidden=random;$('random-interval').hidden=!random;$('gap').disabled=random;$('gap-min').disabled=!random;$('gap-max').disabled=!random;}
function validateIntervals(){const random=$('interval-mode').value==='random';const fields=random?['gap-min','gap-max']:['gap'];for(const k of fields){const el=$(k),fallback=k==='gap-max'?1.5:.5;el.value=String(clamp(el.value.trim()===''?NaN:+el.value,0,10,fallback));}const invalid=random&&+$('gap-min').value>+$('gap-max').value;$('gap-max').setCustomValidity(invalid?t('最长等待不能小于最短等待。'):'');if(!invalid)save();return !invalid;}
for(const b of document.querySelectorAll('[data-interval]'))b.onclick=()=>{$('interval-mode').value=b.dataset.interval;syncIntervals();syncPresets();save();sessionInfo()};
for(const k of ['gap-min','gap-max'])$(k).addEventListener('input',()=>{$('gap-max').setCustomValidity('');syncPresets();save();sessionInfo()});
syncIntervals();
const groupPresets={sets:['1','2','3','4','5','6','8','10'],'set-rest':['0','10','15','20','30','45','60','90','120','180']};
function syncGroupChoice(k){const custom=!groupPresets[k].includes($(k).value);$(k+'-choice').value=custom?'custom':$(k).value;$(k+'-custom-wrap').hidden=!custom;$(k+'-custom').value=$(k).value;}
for(const k of ['sets','set-rest']){
  const input=$(k+'-custom'),min=k==='sets'?1:0,max=k==='sets'?99:600;
  $(k+'-choice').onchange=()=>{const custom=$(k+'-choice').value==='custom';$(k+'-custom-wrap').hidden=!custom;if(custom){input.value=$(k).value;input.focus();}else $(k).value=$(k+'-choice').value;sessionInfo();save();};
  input.oninput=()=>{const n=+input.value;if(input.value!==''&&Number.isFinite(n)&&n>=min&&n<=max){$(k).value=String(Math.floor(n));sessionInfo();save();}};
  input.onchange=()=>{input.value=String(Math.round(clamp(input.value.trim()===''?NaN:+input.value,min,max,+$(k).value)));$(k).value=input.value;sessionInfo();save();};
  syncGroupChoice(k);
}


/* Round presets with a separate custom entry. */
function syncRoundChoice(){const value=$('rounds').value;const preset=['10','20','30','50','100','0'].includes(value);$('rounds-choice').value=preset?value:'custom';$('custom-rounds').hidden=preset;if(!preset)$('rounds-custom').value=value;}
$('rounds-choice').onchange=()=>{const value=$('rounds-choice').value;const custom=value==='custom';$('custom-rounds').hidden=!custom;if(custom){const n=+$('rounds-custom').value;$('rounds').value=String(Number.isFinite(n)&&n>=1?Math.floor(n):20);$('rounds-custom').value=$('rounds').value;$('rounds-custom').focus();}else $('rounds').value=value;save();sessionInfo();};
$('rounds-custom').oninput=()=>{const raw=$('rounds-custom').value;const n=+raw;if(raw!==''&&Number.isFinite(n)&&n>=1){$('rounds').value=String(Math.floor(n));save();sessionInfo()}};
$('rounds-custom').onchange=()=>{$('rounds-custom').value=$('rounds').value==='0'?'20':$('rounds').value;};
syncRoundChoice();
/* Settings dialog: native focus management and keyboard dismissal. */
const settingsDialog=$('settings-dialog');let settingsClosing=false;
function openSettings(){if(settingsDialog.open||settingsClosing)return;settingsDialog.showModal();}
function closeSettings(){if(!settingsDialog.open||settingsClosing)return;settingsClosing=true;settingsDialog.classList.add('is-closing');setTimeout(()=>{settingsDialog.close();settingsDialog.classList.remove('is-closing');settingsClosing=false;},matchMedia('(prefers-reduced-motion: reduce)').matches?0:200);}
$('open-settings').onclick=openSettings;$('close-settings').onclick=closeSettings;$('done-settings').onclick=()=>{if(!validateNumberRange())return;if(validateIntervals()){sessionInfo();closeSettings()}else{$('gap-max').focus();$('gap-max').reportValidity()}};
settingsDialog.addEventListener('cancel',e=>{e.preventDefault();closeSettings()});
settingsDialog.addEventListener('click',e=>{if(e.target!==settingsDialog)return;const r=settingsDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSettings()});
function sessionInfo(){const d=$('dirs').value,n=$('rounds').value,unlimited=n==='0';for(const k of ['sets','set-rest']){const disabled=unlimited||k==='set-rest'&&+$('sets').value<=1;$(k+'-choice').disabled=disabled;$(k+'-custom').disabled=disabled;}$('sets-help').textContent=t(unlimited?'无限循环不分组，结束时手动停止。':+$('sets').value<=1?'单组练习，无组间休息。':'每组完成后休息，倒计时结束自动继续。');$('session-info').textContent=($('training-mode').value==='numbers'?t('数字 {n}',{n:$('number-min').value+'–'+$('number-max').value}):t('{n} 个方向',{n:d}))+' · '+(unlimited?t('无限循环'):t('{sets} 组 × {rounds} 轮',{sets:$('sets').value,rounds:n}))+' · '+($('interval-mode').value==='random'?t('随机间隔'):t('{n} 秒',{n:$('duration').value}));}
for(const k of ['dirs','rounds','duration'])$(k).addEventListener('change',sessionInfo);$('rounds').addEventListener('input',sessionInfo);
$('duration').addEventListener('input',sessionInfo);document.querySelectorAll('[data-speed]').forEach(b=>b.addEventListener('click',sessionInfo));sessionInfo();

/* 首页指针：随机转向，预告练习内容 */
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
let homeAngle=45,homeDir=45;
function spinHome(){
  if($('stage').classList.contains('active')||document.hidden||reduceMotion.matches)return;
  if($('training-mode').value==='numbers'){const lo=+$('number-min').value,hi=+$('number-max').value;if(Number.isInteger(lo)&&Number.isInteger(hi)&&lo<=hi){const n=randomNumber(lo,hi);$('home-number').textContent=n;$('home-number').style.fontSize='clamp(52px,'+Math.min(22,40/String(n).length)+'vmin,160px)';}return;}
  const options=DIRS[8].filter(d=>d!==homeDir);
  const d=options[Math.floor(Math.random()*options.length)];
  homeAngle+=((d-homeDir+540)%360)-180;homeDir=d;
  $('home-arrow').style.transform=`rotate(${homeAngle}deg)`;
  document.querySelectorAll('.tick-mark').forEach(t=>t.classList.toggle('on',+t.dataset.deg===d));
}
setInterval(spinHome,1800);
document.addEventListener('dblclick',e=>e.preventDefault(),{passive:false});
document.addEventListener('keydown',e=>{
  if(settingsDialog.open||document.getElementById('info-dialog')?.open)return;
  if(state==='idle')return;
  if(e.code==='Space'){e.preventDefault();togglePause()}
  if(e.key==='Escape'&&!fullscreenElement()&&performance.now()-lastFullscreenExit>350)exit();
});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&['countdown','arrow','blank','rest'].includes(state))togglePause()});

// Native fullscreen is always opt-in. Unsupported browsers get a brief explanation.
let fullscreenBusy=false,fullscreenNoticeTimer=null,lastFullscreenExit=-Infinity,wasFullscreen=false;
function fullscreenElement(){return document.fullscreenElement||document.webkitFullscreenElement||null;}
function syncFullscreen(){
  const active=!!fullscreenElement();
  if(wasFullscreen&&!active)lastFullscreenExit=performance.now();
  wasFullscreen=active;
  for(const button of document.querySelectorAll('.fullscreen-toggle')){
    button.setAttribute('aria-pressed',String(active));
    button.setAttribute('aria-label',t(active?'退出全屏':'进入全屏'));
    button.title=t(active?'退出全屏':'进入全屏');
    button.querySelector('.expand-icon').classList.toggle('hidden',active);
    button.querySelector('.collapse-icon').classList.toggle('hidden',!active);
  }
}
function fullscreenNotice(message){
  clearTimeout(fullscreenNoticeTimer);$('fullscreen-notice').textContent=t(message);$('fullscreen-notice').hidden=false;
  fullscreenNoticeTimer=setTimeout(()=>{$('fullscreen-notice').hidden=true},6500);
}
async function toggleFullscreen(){
  if(fullscreenBusy)return;
  const root=document.documentElement,active=!!fullscreenElement();
  const request=root.requestFullscreen||root.webkitRequestFullscreen;
  const leave=document.exitFullscreen||document.webkitExitFullscreen;
  if(!active&&(!request||(document.fullscreenEnabled===false&&!document.webkitFullscreenEnabled))){
    fullscreenNotice('此浏览器不支持网页全屏。iPhone 可用 Safari 分享菜单添加到主屏幕后打开。');return;
  }
  fullscreenBusy=true;
  try{
    if(active){if(leave)await leave.call(document);}
    else await request.call(root);
    $('fullscreen-notice').hidden=true;
  }catch{fullscreenNotice('无法进入全屏，请重试或使用其他浏览器。');}
  finally{fullscreenBusy=false;syncFullscreen();}
}
for(const button of document.querySelectorAll('.fullscreen-toggle'))button.addEventListener('click',toggleFullscreen);
document.addEventListener('fullscreenchange',syncFullscreen);
document.addEventListener('webkitfullscreenchange',syncFullscreen);

// Refresh every dynamic label when switching languages, without resetting settings.
function applyLanguage(){
  applyStaticLanguage();syncTrainingMode();syncSound();sessionInfo();syncFullscreen();
  setPauseIcon(state==='paused');updatePhase();
  $('rest-next').textContent=t('下一组 · 第 {current} / {total} 组',{current:set+1,total:config.sets||+$('sets').value});
  if($('number-max').validity.customError)$('number-max').setCustomValidity(t('最大数字不能小于最小数字。'));
  if($('gap-max').validity.customError)$('gap-max').setCustomValidity(t('最长等待不能小于最短等待。'));
}
$('language').addEventListener('change',()=>{applyLanguage();save();document.dispatchEvent(new Event('languagechange'))});
applyLanguage();

// Read-only session state for safe PWA update controls.
window.arrowFlowIsTraining=()=>state!=='idle'&&state!=='done';
